import { useEffect, useRef, useState } from 'react';
import Link from 'next/link';
import { ChevronDown, LogOut, Settings, UserRound } from 'lucide-react';
import { useAuth } from '../../context/AuthContext';
import { useTenant } from '../../context/TenantContext';

export function ExternalAccountMenu({compact=false}){
  const {user,logout}=useAuth(); const {currentMembershipRole,tenantType}=useTenant(); const [open,setOpen]=useState(false); const [busy,setBusy]=useState(false); const root=useRef(null);
  useEffect(()=>{const close=event=>{if(!root.current?.contains(event.target))setOpen(false)};const key=event=>{if(event.key==='Escape')setOpen(false)};document.addEventListener('mousedown',close);document.addEventListener('keydown',key);return()=>{document.removeEventListener('mousedown',close);document.removeEventListener('keydown',key)}},[]);
  const label=user?.name||user?.email||'Consultant'; const initials=label.split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase();
  return <div ref={root} className="relative"><button data-testid="external-account-menu-trigger" aria-haspopup="menu" aria-expanded={open} onClick={()=>setOpen(value=>!value)} className="flex min-h-11 items-center gap-2 rounded-xl border border-slate-200 bg-white px-2.5 text-left hover:bg-slate-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-700"><span className="grid h-8 w-8 place-items-center rounded-full bg-slate-950 text-xs font-bold text-white">{initials||'EC'}</span>{!compact&&<span className="hidden max-w-40 truncate text-sm font-semibold sm:block">{label}</span>}<ChevronDown size={15} className={open?'rotate-180':''}/></button>{open&&<div role="menu" className="fixed right-4 top-20 z-50 w-[calc(100vw-2rem)] max-w-64 rounded-2xl border border-slate-200 bg-white p-2 shadow-2xl sm:absolute sm:right-0 sm:top-full sm:mt-2 sm:w-64"><div className="border-b border-slate-100 px-3 py-3"><p className="truncate text-sm font-bold">{label}</p><p className="mt-1 truncate text-xs text-slate-500">{currentMembershipRole||tenantType?.replaceAll('_',' ')}</p></div><Link href="/profile" role="menuitem" className="mt-1 flex min-h-11 items-center gap-3 rounded-xl px-3 text-sm font-semibold hover:bg-slate-50"><UserRound size={17}/>Profile</Link><Link href="/settings" role="menuitem" className="flex min-h-11 items-center gap-3 rounded-xl px-3 text-sm font-semibold hover:bg-slate-50"><Settings size={17}/>Practice settings</Link><button data-testid="external-logout" role="menuitem" disabled={busy} onClick={async()=>{setBusy(true);await logout();}} className="flex min-h-11 w-full items-center gap-3 rounded-xl px-3 text-left text-sm font-bold text-red-700 hover:bg-red-50 disabled:opacity-50"><LogOut size={17}/>{busy?'Logging out…':'Log out'}</button></div>}</div>;
}
